{"status":"candidate","compute":"data=read('/input/data')
items=sorted(data['items'],key=lambda x:x['id'])
rows=data['rows']
detail=[]
low_ids=[]
for item in items:
    change=0
    for row in rows:
        if row['item']==item['id']:
            change=change+row['delta']
    closing=item['opening']+change
    detail=detail+[{'id':item['id'],'opening':item['opening'],'change':change,'closing':closing}]
    if closing<=item['minimum']:
        low_ids=low_ids+[item['id']]
opening_total=sum([x['opening'] for x in detail])
change_total=sum([x['change'] for x in detail])
closing_total=sum([x['closing'] for x in detail])
summary={'opening':opening_total,'change':change_total,'closing':closing_total,'low_ids':low_ids}
result={'detail':detail,'summary':summary}","effects":"","reason":"Compute the reconciliation from the input, sort details by item id, and derive low_ids using each item's minimum.","reason_code":"NONE"}
